2	 * Subscription rows; one active row per organization.
3	 */
4	import { and, eq, isNotNull, lte, ne } from "drizzle-orm";
5	import { newId } from "@/lib/id";
6	import { getDb, subscriptions } from "@/server/db";
7	import { toIsoTimestamp } from "@/types/common";
8	import { orgPredicate } from "./base-repository";
9	import { toSubscription } from "./_mappers";
10	import type { BillingInterval, PlanId, Subscription } from "@/types/billing";
11	import type { IsoTimestamp, OrgId } from "@/types/common";
12	
13	const MS_PER_DAY = 24 * 60 * 60 * 1000;
14	const TRIAL_DAYS = 14;
15	
16	export async function findSubscription(
17	  orgId: OrgId,
18	): Promise<Subscription | null> {
19	  const row = getDb()
20	    .select()
21	    .from(subscriptions)
22	    .where(orgPredicate(subscriptions.orgId, orgId))
23	    .get();
24	  return row ? toSubscription(row) : null;
25	}
26	
27	/** New organizations start on a trial period rather than an active plan. */
28	export async function insertSubscription(
29	  orgId: OrgId,
30	  plan: PlanId,
31	  interval: BillingInterval,
32	): Promise<Subscription> {
33	  const now = new Date();
34	  const stamp = toIsoTimestamp(now);
35	  const periodEnd = toIsoTimestamp(
36	    new Date(now.getTime() + TRIAL_DAYS * MS_PER_DAY),
37	  );
38	
39	  const row = getDb()
40	    .insert(subscriptions)
41	    .values({
42	      id: newId(),
43	      orgId,
44	      plan,
45	      interval,
46	      status: plan === "free" ? "active" : "trialing",
47	      seats: 1,
48	      currentPeriodStart: stamp,
49	      currentPeriodEnd: periodEnd,
50	      cancelAt: null,
51	      createdAt: stamp,
52	      updatedAt: stamp,
53	    })
54	    .returning()
55	    .get();
56	
57	  return toSubscription(row);
58	}
59	
60	/** A plan change ends the trial: the org has made a deliberate choice. */
61	export async function updateSubscriptionPlan(
62	  orgId: OrgId,
63	  plan: PlanId,
64	  interval: BillingInterval,
65	): Promise<Subscription> {
66	  const stamp = toIsoTimestamp(new Date());
67	  const row = getDb()
68	    .update(subscriptions)
69	    .set({ plan, interval, status: "active", updatedAt: stamp })
70	    .where(orgPredicate(subscriptions.orgId, orgId))
71	    .returning()
72	    .get();
73	
74	  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
75	  return toSubscription(row);
76	}
77	
78	export async function updateSeatCount(
79	  orgId: OrgId,
80	  seats: number,
81	): Promise<Subscription> {
82	  const row = getDb()
83	    .update(subscriptions)
84	    .set({ seats, updatedAt: toIsoTimestamp(new Date()) })
85	    .where(orgPredicate(subscriptions.orgId, orgId))
86	    .returning()
87	    .get();
88	
89	  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
90	  return toSubscription(row);
91	}
92	
93	/** `cancelAt === null` reactivates a subscription scheduled for cancellation. */
94	export async function cancelSubscription(
95	  orgId: OrgId,
96	  cancelAt: IsoTimestamp | null,
97	): Promise<Subscription> {
98	  const row = getDb()
99	    .update(subscriptions)
100	    .set({
101	      cancelAt,
102	      status: cancelAt === null ? "active" : "canceled",
